  var tokenSpark = [3.1, 3.4, 2.8, 4.2, 5.1, 4.6, 6.2, 7.4, 6.8, 8.1, 7.2, 6.4, 7.8, 9.4, 8.6, 7.9, 8.8, 9.9, 8.4, 7.1, 6.2, 5.4, 4.8, 5.2];
