      't': manualTick, 'T': manualTick, 'c': function () { go('chat/' + (liveChatAgents()[0] || 'core-headless')); }, 'C': function () { go('chat/' + (liveChatAgents()[0] || 'core-headless')); },
      'w': function () { go('welcome'); }, 'W': function () { go('welcome'); },
